/* New-publication evidence only. Local results win; duplicate or conflicting
 * provider meetings cannot artificially amplify this deliberately weak signal. */
function pp_analysis_provider_h2h(array $analysis,array $provider,array $match,DateTimeImmutable $now):array {
 if(($match['date']??'')<'2026-10-24'||!$provider)return $analysis;
 $cut=min($now->getTimestamp(),pp_analysis_time($match)??$now->getTimestamp());$rows=[];$conflicts=[];$remote=[];
 $valid=static function(array $r)use($cut):?array{$t=strtotime((string)($r['date']??''));if(!$t||$t>=$cut||$cut-$t>550*86400)return null;foreach(['home','away']as$s)if(!isset($r[$s])||!is_int($r[$s])||$r[$s]<0||$r[$s]>30)return null;return ['date'=>gmdate(DATE_ATOM,$t),'home'=>$r['home'],'away'=>$r['away'],'time'=>$t,'key'=>(new DateTimeImmutable('@'.$t))->setTimezone(new DateTimeZone('Europe/Istanbul'))->format('Y-m-d')];};
 foreach($analysis['h2h']['recent']??[]as$r)if(is_array($r)&&($v=$valid($r)))$rows[$v['key']]=array_merge($v,['source'=>'verified-completed-history']);
 foreach($provider as$r){if(!is_array($r)||($r['source']??'')!=='ESPN-verified-completed-series'||!($v=$valid($r)))continue;$k=$v['key'];if(isset($rows[$k])){if($rows[$k]['home']!==$v['home']||$rows[$k]['away']!==$v['away'])$conflicts[$k]=true;continue;}if(isset($remote[$k])&&($remote[$k]['home']!==$v['home']||$remote[$k]['away']!==$v['away'])){$conflicts[$k]=true;unset($remote[$k]);continue;}if(!isset($conflicts[$k]))$remote[$k]=array_merge($v,['source'=>'ESPN-verified-completed-series']);}
 $all=array_values($rows+$remote);usort($all,fn($a,$b)=>$b['time']<=>$a['time']);$all=array_slice($all,0,5);$added=count(array_filter($all,fn($r)=>$r['source']==='ESPN-verified-completed-series'));if(!$added){if($conflicts)$analysis['h2h']['providerConflictsIgnored']=count($conflicts);return $analysis;}
 $local=$analysis['h2h']??[];$old=((int)($local['homeWins']??0)-(int)($local['awayWins']??0))/((int)($local['matches']??0)+8)*.035;$weight=0.0;$balance=0.0;$h2h=['matches'=>count($all),'homeWins'=>0,'draws'=>0,'awayWins'=>0,'recent'=>[],'providerMatchesAdded'=>$added,'providerConflictsIgnored'=>count($conflicts),'policy'=>'latest-five-deduplicated-550-days-age-shrunk'];
 foreach($all as$r){$w=pow(.5,($cut-$r['time'])/(365*86400));$weight+=$w;$balance+=$w*($r['home']<=>$r['away']);$h2h[$r['home']>$r['away']?'homeWins':($r['home']===$r['away']?'draws':'awayWins')]++;unset($r['time'],$r['key']);$h2h['recent'][]=$r;}
 $edge=$balance/($weight+8)*.035;$h2h['weightedMatches']=round($weight,5);$h2h['modelEdge']=round($edge,7);$analysis['h2h']=$h2h;$analysis['coverage']['h2h']=true;$analysis['coverage']['providerH2h']=true;
 foreach(['home'=>1,'away'=>-1]as$s=>$sign)$analysis['contextFactors'][$s]=round(exp(pp_analysis_clip(log(max(.1,(float)($analysis['contextFactors'][$s]??1)))+$sign*($edge-$old),-.1,.1)),5);
 $analysis['h2hEvidenceNote']='Completed, identity-checked meetings only; local results take precedence, conflicting provider duplicates are excluded, older meetings have less weight.';return $analysis;
}
